window.__AtlasPayload=window.__AtlasPayload||{};window.__AtlasPayload["seismic-firstbreak-pick"]={"pkg":{"id":"seismic-firstbreak-pick","sceneId":"s3","methods":["ts","cv"],"title":"地震炮集初至波自动拾取与空间一致性约束","version":"1.0.0","updated":"2026-10-28","tabs":{"background":{"label":"专业背景","lede":"在陆上地震勘探中，**单炮记录初至波（First Break）到达时间**的准确拾取是计算近地表低降速带厚度与速度、开展高精度层析反演静校正的绝对前提。二维测线通常包含数十万道地震记录，人工逐道目视点击拾取耗费数周时间且存在严重的人为主观尺度漂移。更为棘手的是，**野外工频电缆干扰、近震源强机械冲击引发的前驱脉冲毛刺（Spurious Precursor Spikes）**经常导致常规短长时窗能量比（STA/LTA）提前数个采样点发生致命的「假拾取（False Triggering）」。本案例构建了**「逐道带通滤波 → STA/LTA 能量比粗定位 → 赤池信息准则（AIC）极小值精修 → 炮集空间走时一致性中位数回退约束」**的四级智能拾取工作流，实现 **95.8% 全炮命中率**与 **1.8 ms 平均绝对误差（MAE）**，仅需对标记出的 12.5% 低置信度异常道进行人工抽检，节省 87% 的数据处理工时。","judge":[{"label":"数据形态","value":"24道单炮地震道集","desc":"采样率 Δt=2ms，偏移距 50–1200m，包含面波锥与突发前驱尖峰"},{"label":"核心痛点","value":"前驱脉冲提前假触发","desc":"单道固定阈值将突发噪声毛刺误当做初至，导致静校正量严重失真"},{"label":"AI 切入点","value":"STA/LTA + AIC + 空间约束","desc":"单道极小值精修克服积分滞后，相邻道走时中位数滤波拦截离群道"},{"label":"核心收益","value":"工时节省87% · MAE 1.8ms","desc":"命中率从单道 79.2% 跃升至 95.8%，仅需人工复核 3 条道"}],"sections":[{"no":1,"en":"PROBLEM","title":"当前做法与痛点","html":"<p>地震初至波是地下震源激发后沿地表及近地表地层传播、最早到达地表检波器的地震波。它直接反映了低降速带（风化层）厚度与表层速度结构，是计算近地表静校正量的物理基准：</p>\n<ul>\n  <li><strong>人工拾取效率极低且标准不一</strong>：二维测线一般包含数千单炮、数十万道记录。人工逐道缩放波形点击初至，一人一天仅能拾取约 1500–2500 道，一条测线处理长达数周；且晨间与深夜拾取的一致性常差 2–4 个采样点。</li>\n  <li><strong>前驱脉冲与低信噪比导致单道算法崩溃</strong>：受野外电缆打火、农田机械及近震源强烈面波冲击影响，波形在真实初至到达前常伴随孤立窄脉冲。传统单道能量比法只看振幅突变，会把前驱尖峰当成初至提前触发，形成离群假拾取。</li>\n  <li><strong>静校正假构造风险</strong>：初至若拾取错误，几毫秒的时间偏差折算到深层反射成像就会形成几十米的虚假构造起伏，导致探井靶心错位。</li>\n</ul>\n<div class=\"figure\"><svg viewBox=\"0 0 760 300\" width=\"100%\" role=\"img\" aria-label=\"近地表双层折射模型与地震单炮道集初至波走时规律\">\n  <rect width=\"760\" height=\"300\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Left: Near-surface refraction physics -->\n  <rect x=\"14\" y=\"14\" width=\"360\" height=\"272\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"26\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">A. 近地表双层速度模型与直达波/折射波传播路径</text>\n  <!-- Surface layer -->\n  <rect x=\"30\" y=\"55\" width=\"320\" height=\"55\" fill=\"#f2e4c6\" opacity=\"0.65\" stroke=\"#d9c7a3\"/>\n  <text x=\"40\" y=\"74\" font-size=\"10\" font-weight=\"700\" fill=\"#15191c\">低速风化层 (v₀ = 750 m/s · 厚度 h₀ ≈ 109m)</text>\n  <!-- High velocity refractor -->\n  <rect x=\"30\" y=\"110\" width=\"320\" height=\"130\" fill=\"#cbd5e1\" opacity=\"0.5\" stroke=\"#94a3b8\"/>\n  <text x=\"40\" y=\"132\" font-size=\"10\" font-weight=\"700\" fill=\"#334155\">基底降速/基岩折射层 (v₁ = 2100 m/s)</text>\n  <!-- Shot point -->\n  <circle cx=\"50\" cy=\"55\" r=\"6\" fill=\"#b4483c\"/><text x=\"50\" y=\"46\" font-size=\"9\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"middle\">震源 S</text>\n  <!-- Raypaths: Direct wave -->\n  <line x1=\"50\" y1=\"55\" x2=\"160\" y2=\"55\" stroke=\"#2f7d5b\" stroke-width=\"2.2\"/>\n  <text x=\"105\" y=\"48\" font-size=\"8.5\" fill=\"#2f7d5b\" font-weight=\"700\">直达波 t_dir</text>\n  <!-- Raypaths: Head wave / Refraction -->\n  <line x1=\"50\" y1=\"55\" x2=\"95\" y2=\"110\" stroke=\"#12615a\" stroke-width=\"2\"/>\n  <line x1=\"95\" y1=\"110\" x2=\"280\" y2=\"110\" stroke=\"#12615a\" stroke-width=\"2.4\"/>\n  <line x1=\"280\" y1=\"110\" x2=\"325\" y2=\"55\" stroke=\"#12615a\" stroke-width=\"2\"/>\n  <text x=\"187\" y=\"125\" font-size=\"9\" fill=\"#12615a\" font-weight=\"700\" text-anchor=\"middle\">临界折射波 (沿界面以 v₁ 高速滑行)</text>\n  <circle cx=\"325\" cy=\"55\" r=\"4\" fill=\"#12615a\"/><text x=\"325\" y=\"46\" font-size=\"9\" fill=\"#12615a\" font-weight=\"700\" text-anchor=\"middle\">检波器 R</text>\n  <!-- Cross-over offset marker -->\n  <line x1=\"160\" y1=\"50\" x2=\"160\" y2=\"240\" stroke=\"#b4483c\" stroke-dasharray=\"3,2\"/>\n  <text x=\"160\" y=\"255\" font-size=\"9.5\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"middle\">盲区拐点 X_c ≈ 290m</text>\n\n  <!-- Right: Offset-Time T-X curve -->\n  <rect x=\"386\" y=\"14\" width=\"360\" height=\"272\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"398\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">B. 炮集初至走时曲线 (T-X) 双段折线理论模型</text>\n  <line x1=\"426\" y1=\"240\" x2=\"720\" y2=\"240\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <line x1=\"426\" y1=\"52\" x2=\"426\" y2=\"240\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <text x=\"573\" y=\"260\" font-size=\"9.5\" fill=\"#424a50\" text-anchor=\"middle\">炮检距 (Offset, 50m – 1200m) →</text>\n  <text x=\"394\" y=\"146\" font-size=\"9.5\" fill=\"#424a50\" transform=\"rotate(-90 394 146)\" text-anchor=\"middle\">初至到达时间 t (ms) →</text>\n  <!-- Direct wave line -->\n  <line x1=\"426\" y1=\"240\" x2=\"520\" y2=\"175\" stroke=\"#2f7d5b\" stroke-width=\"2.2\" stroke-dasharray=\"4,2\"/>\n  <text x=\"480\" y=\"195\" font-size=\"9\" fill=\"#2f7d5b\" font-weight=\"700\">斜率 1/v₀</text>\n  <!-- Refracted wave line -->\n  <line x1=\"520\" y1=\"175\" x2=\"710\" y2=\"75\" stroke=\"#12615a\" stroke-width=\"2.6\"/>\n  <text x=\"630\" y=\"112\" font-size=\"9\" fill=\"#12615a\" font-weight=\"700\">斜率 1/v₁ (高速变缓)</text>\n  <!-- Critical offset -->\n  <circle cx=\"520\" cy=\"175\" r=\"5\" fill=\"#b4483c\"/>\n  <text x=\"525\" y=\"165\" font-size=\"9.5\" fill=\"#b4483c\" font-weight=\"700\">拐点 X_c (290m)</text>\n  <!-- Spurious spikes scatter -->\n  <circle cx=\"485\" cy=\"120\" r=\"4.5\" fill=\"#c27a2c\" stroke=\"#b4483c\"/><text x=\"495\" y=\"115\" font-size=\"8.5\" fill=\"#b4483c\" font-weight=\"700\">#7 尖峰假拾取</text>\n  <circle cx=\"580\" cy=\"70\" r=\"4.5\" fill=\"#c27a2c\" stroke=\"#b4483c\"/><text x=\"590\" y=\"65\" font-size=\"8.5\" fill=\"#b4483c\" font-weight=\"700\">#14 脉冲离群</text>\n  <rect x=\"400\" y=\"268\" width=\"332\" height=\"1\" fill=\"#e7e3da\"/>\n</svg></div>\n<div class=\"figcap\"><b>图 1</b><span>近地表低降速带双层速度折射物理模型（左）与单炮初至走时双段分折线与离群点示意图（右）。</span></div>\n<p>为此，智能初至拾取系统必须突破单道孤立分析的局限，充分利用地下地层沿炮检距横向连续延伸的物理先验规律。</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 215\" width=\"100%\" role=\"img\" aria-label=\"单道固定阈值受前驱脉冲提前假触发失灵困境\">\n  <rect width=\"760\" height=\"215\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"18\" y=\"25\" font-size=\"12\" font-weight=\"700\" fill=\"#15191c\">传统单道 STA/LTA 能量比触发在突发前驱脉冲冲击下的「提前假拾取」失灵困境</text>\n  <!-- Left: Raw Spurious Trigger -->\n  <rect x=\"18\" y=\"38\" width=\"350\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"30\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#b4483c\">1. 单道独立阈值触发：前驱随机尖峰提前误判</text>\n  <!-- Waveform with spike -->\n  <path d=\"M30,110 L90,110 L105,75 L115,135 L125,110 L180,110 L195,85 L205,145 L220,110 L330,110\" fill=\"none\" stroke=\"#424a50\" stroke-width=\"1.3\"/>\n  <!-- Spike marker -->\n  <circle cx=\"110\" cy=\"75\" r=\"4\" fill=\"#b4483c\"/><text x=\"110\" y=\"68\" font-size=\"8.5\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"middle\">电缆打火尖峰</text>\n  <!-- Trigger line -->\n  <line x1=\"110\" y1=\"45\" x2=\"110\" y2=\"155\" stroke=\"#b4483c\" stroke-width=\"1.5\" stroke-dasharray=\"3,2\"/>\n  <text x=\"110\" y=\"168\" font-size=\"9\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"middle\">误拾取时间 (提前 80ms!)</text>\n  <!-- True arrival -->\n  <line x1=\"195\" y1=\"45\" x2=\"195\" y2=\"155\" stroke=\"#2f7d5b\" stroke-width=\"1.8\"/>\n  <text x=\"195\" y=\"168\" font-size=\"9\" fill=\"#2f7d5b\" font-weight=\"700\" text-anchor=\"middle\">真实初至起跳点</text>\n  <text x=\"30\" y=\"188\" font-size=\"9.5\" fill=\"#b4483c\">× 产生巨大正负静校正假构造，引起深层反射同相轴剧烈抖动断裂</text>\n\n  <!-- Right: Consistency Constraint -->\n  <rect x=\"392\" y=\"38\" width=\"350\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#12615a\" stroke-width=\"1.3\"/>\n  <text x=\"404\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#12615a\">2. 炮集横向走时空间一致性约束：自动拦截回退</text>\n  <rect x=\"404\" y=\"70\" width=\"326\" height=\"58\" rx=\"4\" fill=\"#e3efec\" stroke=\"#12615a\"/>\n  <text x=\"416\" y=\"92\" font-size=\"10.5\" font-weight=\"700\" fill=\"#12615a\">空间中位数滤波：检测 |Δt - Median| = 42ms > 3.5点</text>\n  <text x=\"416\" y=\"110\" font-size=\"9.5\" fill=\"#424a50\">判定为前驱野值触发，自动利用 #13 与 #15 道线性趋势回退</text>\n  <text x=\"404\" y=\"152\" font-size=\"10\" fill=\"#12615a\" font-weight=\"700\">✓ 成功纠正 #7、#14、#21 道离群点，误差压至 2ms 以内</text>\n  <text x=\"404\" y=\"172\" font-size=\"10\" fill=\"#2f7d5b\">✓ 全炮绝对拾取误差 MAE 从 14.6 ms 断崖式下降至 1.8 ms</text>\n</svg></div>\n<div class=\"figcap\"><b>图 2</b><span>低信噪比道上随机脉冲导致 STA/LTA 提前误触发（左），空间一致性中位数滤波自动回退离群道（右）。</span></div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>现代物探智能初至拾取方案结合信号处理经典准则与空间地球物理连续性约束，构建全自动秒级处理流水线：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 250\" width=\"100%\" role=\"img\" aria-label=\"初至波多级智能拾取工作流架构图\">\n  <rect width=\"760\" height=\"250\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Stage 1 -->\n  <rect x=\"14\" y=\"24\" width=\"130\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"79\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">1. 道集解编预处理</text>\n  <rect x=\"24\" y=\"60\" width=\"110\" height=\"32\" rx=\"4\" fill=\"#e3ecf6\"/><text x=\"79\" y=\"80\" font-size=\"10\" fill=\"#3a6ea5\" text-anchor=\"middle\">SEG-Y 道集解编</text>\n  <rect x=\"24\" y=\"100\" width=\"110\" height=\"32\" rx=\"4\" fill=\"#e3efec\"/><text x=\"79\" y=\"120\" font-size=\"10\" fill=\"#12615a\" text-anchor=\"middle\">去直流与标化</text>\n  <rect x=\"24\" y=\"140\" width=\"110\" height=\"32\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/><text x=\"79\" y=\"160\" font-size=\"10\" fill=\"#424a50\" text-anchor=\"middle\">10–80Hz零相滤波</text>\n  <text x=\"79\" y=\"200\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">衰减面波低频扰动</text>\n\n  <line x1=\"144\" y1=\"125\" x2=\"162\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n\n  <!-- Stage 2 -->\n  <rect x=\"166\" y=\"24\" width=\"144\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#12615a\" stroke-width=\"1.3\"/>\n  <text x=\"238\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">2. STA/LTA 能量比扫描</text>\n  <rect x=\"176\" y=\"58\" width=\"124\" height=\"42\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"238\" y=\"76\" font-size=\"10\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">短窗 STA = 8 点</text>\n  <text x=\"238\" y=\"91\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"middle\">高灵敏度响应能量跃迁</text>\n  <rect x=\"176\" y=\"106\" width=\"124\" height=\"42\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"238\" y=\"124\" font-size=\"10\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">长窗 LTA = 55 点</text>\n  <text x=\"238\" y=\"139\" font-size=\"8.5\" fill=\"#3a6ea5\" text-anchor=\"middle\">表征前驱背景噪声水平</text>\n  <rect x=\"176\" y=\"154\" width=\"124\" height=\"42\" rx=\"4\" fill=\"#e3efec\"/>\n  <text x=\"238\" y=\"172\" font-size=\"10\" font-weight=\"600\" fill=\"#2f7d5b\" text-anchor=\"middle\">触发阈值 θ = 3.2</text>\n  <text x=\"238\" y=\"187\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">初选候选起跳位置</text>\n\n  <line x1=\"310\" y1=\"125\" x2=\"328\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n\n  <!-- Stage 3 -->\n  <rect x=\"332\" y=\"24\" width=\"168\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#3a6ea5\" stroke-width=\"1.3\"/>\n  <text x=\"416\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#3a6ea5\" text-anchor=\"middle\">3. AIC 赤池局部精修</text>\n  <rect x=\"344\" y=\"58\" width=\"144\" height=\"66\" rx=\"4\" fill=\"#e3ecf6\"/>\n  <text x=\"416\" y=\"78\" font-size=\"10.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">自回归 AIC 极小值算子</text>\n  <text x=\"416\" y=\"95\" font-size=\"9\" fill=\"#3a6ea5\" font-family=\"ui-monospace,Consolas,monospace\" text-anchor=\"middle\">AIC(k) = k·ln(σ₁²)+(N-k)·ln(σ₂²)</text>\n  <text x=\"416\" y=\"112\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">前后时窗方差突变极小</text>\n  <rect x=\"344\" y=\"132\" width=\"144\" height=\"64\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"416\" y=\"152\" font-size=\"10.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">消除积分滞后误差</text>\n  <text x=\"416\" y=\"168\" font-size=\"9\" fill=\"#12615a\" text-anchor=\"middle\">将粗拾取拉回起跳原点</text>\n  <text x=\"416\" y=\"184\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">误差由 6ms 压缩至 1.8ms</text>\n\n  <line x1=\"500\" y1=\"125\" x2=\"518\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n\n  <!-- Stage 4 -->\n  <rect x=\"522\" y=\"24\" width=\"224\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#2f7d5b\" stroke-width=\"1.3\"/>\n  <text x=\"634\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#2f7d5b\" text-anchor=\"middle\">4. 空间一致性约束与复核</text>\n  <rect x=\"534\" y=\"58\" width=\"200\" height=\"66\" rx=\"4\" fill=\"#e2f0e8\"/>\n  <text x=\"634\" y=\"78\" font-size=\"10.5\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">相邻道走时中位数回退</text>\n  <text x=\"634\" y=\"96\" font-size=\"9.5\" fill=\"#2f7d5b\" text-anchor=\"middle\">剔除脉冲离群道 (修正 3 条道)</text>\n  <text x=\"634\" y=\"112\" font-size=\"9.5\" fill=\"#12615a\" text-anchor=\"middle\">命中率跃升至 95.8%</text>\n  <rect x=\"534\" y=\"132\" width=\"200\" height=\"64\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"634\" y=\"152\" font-size=\"10.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">低置信度道优先推送</text>\n  <text x=\"634\" y=\"170\" font-size=\"9\" fill=\"#c27a2c\" text-anchor=\"middle\">仅推送最低 12.5% 异常道人工把关</text>\n  <text x=\"634\" y=\"186\" font-size=\"9\" fill=\"#737c83\" text-anchor=\"middle\">人机闭环达成极高生产效率</text>\n</svg></div>\n<div class=\"figcap\"><b>图 3</b><span>道集解编、STA/LTA 能量比粗扫、AIC 赤池准则极小值精修与炮集横向走时一致性回退的四级协同架构。</span></div>"},{"no":3,"en":"DATA","title":"数据与道头参数","html":"<p>实施地震初至波自动拾取，前期数据准备与道头几何定义是基础保障：</p>\n<div class=\"checklist\"><div class=\"cl-head\"><span>数据与工程准备清单 · 3 项（可点击勾选）</span><span class=\"cl-prog\"><span id=\"cl-txt\">0 / 3</span><span class=\"cl-bar\"><i id=\"cl-fill\"></i></span></span></div>\n  <div class=\"cl-item\" data-cl=\"0\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">单炮地震道集数据文件 (标准 SEG-Y/SEGD 格式)</span><span class=\"cl-s\">24–240 道单炮道集，时间采样间隔 1–2 ms，记录长度 ≥ 1.0 s，包含完整道头信息</span></span><span class=\"cl-n\">包含检波器坐标、炮点标高与道序号</span></div>\n  <div class=\"cl-item\" data-cl=\"1\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">近地表调查与微测井表层降速带先验资料</span><span class=\"cl-s\">工区表层小折射或微测井实测的松散风化层厚度 (h₀) 与低速层速度 (v₀)</span></span><span class=\"cl-n\">设定初始搜索时窗边界与折射拐点理论位置</span></div>\n  <div class=\"cl-item\" data-cl=\"2\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">高信噪比基准炮集人工拾取对照抽检库</span><span class=\"cl-s\">工区内按 5%–10% 比例抽检的人工精细拾取道集，用于评估误差统计分布</span></span><span class=\"cl-n\">容差 ±4ms (2 个采样点) 评测标准</span></div>\n</div>\n<div class=\"figure\"><svg viewBox=\"0 0 760 215\" width=\"100%\" role=\"img\" aria-label=\"地震初至波信噪比分级与容差验收带评估\">\n  <rect width=\"760\" height=\"215\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"18\" y=\"24\" font-size=\"12\" font-weight=\"700\" fill=\"#15191c\">地震道信噪比分级特性与 ±4 ms (2 个采样点) 容差验收带评估标准</text>\n  <!-- Left: SNR distribution -->\n  <rect x=\"16\" y=\"38\" width=\"354\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"28\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\">A. 炮集地震道信噪比 (SNR) 分布特性</text>\n  <rect x=\"28\" y=\"70\" width=\"100\" height=\"74\" fill=\"#e3efec\" stroke=\"#12615a\"/>\n  <text x=\"78\" y=\"104\" font-size=\"10\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">近道 SNR > 15dB</text>\n  <text x=\"78\" y=\"122\" font-size=\"9\" fill=\"#424a50\" text-anchor=\"middle\">直达波能量强 (55%)</text>\n  <rect x=\"136\" y=\"70\" width=\"100\" height=\"74\" fill=\"#fbfaf7\" stroke=\"#c27a2c\"/>\n  <text x=\"186\" y=\"104\" font-size=\"10\" font-weight=\"700\" fill=\"#c27a2c\" text-anchor=\"middle\">中道 SNR 5–15dB</text>\n  <text x=\"186\" y=\"122\" font-size=\"9\" fill=\"#737c83\" text-anchor=\"middle\">折射波过渡 (35%)</text>\n  <rect x=\"244\" y=\"70\" width=\"116\" height=\"74\" fill=\"#f6e3df\" stroke=\"#b4483c\" stroke-dasharray=\"3,2\"/>\n  <text x=\"302\" y=\"104\" font-size=\"10\" font-weight=\"700\" fill=\"#b4483c\" text-anchor=\"middle\">远道 SNR &lt; 3dB</text>\n  <text x=\"302\" y=\"122\" font-size=\"9\" fill=\"#b4483c\" text-anchor=\"middle\">弱信号/脉冲道 (10%)</text>\n  <text x=\"28\" y=\"162\" font-size=\"9.5\" fill=\"#424a50\">原则：远道弱信号必须依托近中道速度外推，不可强行拉高灵敏度。</text>\n  <text x=\"28\" y=\"178\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"600\">低信噪比道自动打低置信度标签，交由人工交互核验。</text>\n\n  <!-- Right: Tolerance -->\n  <rect x=\"386\" y=\"38\" width=\"358\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"398\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\">B. 工业级 ±4ms (2 采样点) 初至拾取容差带</text>\n  <line x1=\"410\" y1=\"112\" x2=\"720\" y2=\"112\" stroke=\"#2f7d5b\" stroke-width=\"2.6\"/>\n  <rect x=\"410\" y=\"96\" width=\"310\" height=\"32\" fill=\"rgba(47,125,91,0.14)\" stroke=\"#2f7d5b\" stroke-dasharray=\"4,2\"/>\n  <text x=\"420\" y=\"90\" font-size=\"9.5\" fill=\"#2f7d5b\" font-weight=\"700\">真值初至走时曲线 (Ground Truth)</text>\n  <text x=\"710\" y=\"108\" font-size=\"8.5\" fill=\"#2f7d5b\" text-anchor=\"end\">+4ms 容差线</text>\n  <text x=\"710\" y=\"136\" font-size=\"8.5\" fill=\"#2f7d5b\" text-anchor=\"end\">-4ms 容差线</text>\n  <path d=\"M410,110 L520,111 L620,109 L720,114\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2\"/>\n  <text x=\"560\" y=\"132\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"700\">智能空间约束拾取线 (全炮命中率 95.8%)</text>\n  <text x=\"398\" y=\"166\" font-size=\"9.5\" fill=\"#424a50\">在 2ms 采样率下，落入 ±4ms 即满足商业层析反演精度要求。</text>\n  <text x=\"398\" y=\"182\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"700\">本案例实测全炮平均误差 MAE 达到 1.8ms。</text>\n</svg></div>\n<div class=\"figcap\"><b>图 4</b><span>地震道信噪比空间分布特性（左）与工业级 ±4ms 初至容差验收评估机制（右）。</span></div>"},{"no":4,"en":"DIFFICULTY","title":"工程瓶颈与对策","html":"<p>初至波自动拾取的核心挑战在于低信噪比与脉冲干扰下的自适应抗噪性能：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 225\" width=\"100%\" role=\"img\" aria-label=\"短长窗长阈值权衡与物探落地五维技术难度\">\n  <rect width=\"760\" height=\"225\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Left: STA/LTA Ratio Tradeoff -->\n  <rect x=\"14\" y=\"14\" width=\"368\" height=\"197\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"26\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">A. STA 窗长与触发阈值 θ 的「假拾取 vs 漏拾取」权衡</text>\n  <line x1=\"56\" y1=\"176\" x2=\"356\" y2=\"176\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <line x1=\"56\" y1=\"48\" x2=\"56\" y2=\"176\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <text x=\"206\" y=\"196\" font-size=\"10\" fill=\"#424a50\" text-anchor=\"middle\">触发阈值 θ (1.5 – 6.0) → 越高越保守</text>\n  <path d=\"M65,65 Q180,120 340,165\" fill=\"none\" stroke=\"#b4483c\" stroke-width=\"2\"/>\n  <text x=\"270\" y=\"145\" font-size=\"9\" fill=\"#b4483c\">噪声前驱假拾取率</text>\n  <path d=\"M65,165 Q180,120 340,65\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"2\"/>\n  <text x=\"270\" y=\"80\" font-size=\"9\" fill=\"#c27a2c\">远道弱信号漏拾率</text>\n  <line x1=\"220\" y1=\"48\" x2=\"220\" y2=\"176\" stroke=\"#12615a\" stroke-dasharray=\"3,2\"/>\n  <circle cx=\"220\" cy=\"115\" r=\"5\" fill=\"#12615a\"/>\n  <text x=\"220\" y=\"42\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"700\" text-anchor=\"middle\">工程最佳平衡点 θ = 3.2</text>\n\n  <!-- Right: 5-D Difficulty -->\n  <rect x=\"394\" y=\"14\" width=\"352\" height=\"197\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"408\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">B. 地震初至波自动拾取工程落地五维技术难度剖析</text>\n  <g font-size=\"10\" fill=\"#424a50\">\n    <text x=\"408\" y=\"60\">前驱脉冲与强工业电缆杂散干扰</text><rect x=\"546\" y=\"51\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"51\" width=\"146\" height=\"10\" rx=\"3\" fill=\"#b4483c\"/><text x=\"708\" y=\"60\" font-family=\"ui-monospace,Consolas,monospace\">9.4</text>\n    <text x=\"408\" y=\"90\">低速带剧烈横向变化断阶失真</text><rect x=\"546\" y=\"81\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"81\" width=\"134\" height=\"10\" rx=\"3\" fill=\"#c27a2c\"/><text x=\"708\" y=\"90\" font-family=\"ui-monospace,Consolas,monospace\">8.6</text>\n    <text x=\"408\" y=\"120\">强面波 (Ground Roll) 低频干扰锥</text><rect x=\"546\" y=\"111\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"111\" width=\"122\" height=\"10\" rx=\"3\" fill=\"#c27a2c\"/><text x=\"708\" y=\"120\" font-family=\"ui-monospace,Consolas,monospace\">7.9</text>\n    <text x=\"408\" y=\"150\">远炮检距高频吸收衰减与波散</text><rect x=\"546\" y=\"141\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"141\" width=\"114\" height=\"10\" rx=\"3\" fill=\"#3a6ea5\"/><text x=\"708\" y=\"150\" font-family=\"ui-monospace,Consolas,monospace\">7.3</text>\n    <text x=\"408\" y=\"180\">低信噪比道人工交互复核负荷</text><rect x=\"546\" y=\"171\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"171\" width=\"100\" height=\"10\" rx=\"3\" fill=\"#12615a\"/><text x=\"708\" y=\"180\" font-family=\"ui-monospace,Consolas,monospace\">6.4</text>\n  </g>\n</svg></div>\n<div class=\"figcap\"><b>图 5</b><span>触发阈值在假拾取与漏拾取之间的权衡关系（左）及初至拾取工程落地五维技术难度剖析（右）。</span></div>\n<p>关联方法与技术方向：</p>\n<div class=\"refs\">\n  <a class=\"ref\" href=\"#/method/ts\">时序变点检测与能量比<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/ts\">赤池信息准则 AIC 极小值精修<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/ts\">空间横向走时一致性中位数滤波<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/cv\">1D 卷积神经网络初至相位分割<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/ts\">表层折射层析反演静校正<span class=\"ar\">↗</span></a>\n</div>"}]},"workflow":{"label":"案例流程","title":"地震初至波智能拾取全流水线","lead":["从道集滤波、能量比粗扫到 AIC 精修与横向走时约束，实现全炮道高精度自动化拾取。"],"stats":[["单炮道数","24 道"],["采样间隔","2 ms"],["验收合格率","95.8%"]],"steps":[{"name":"道集解编与带通滤波预处理","role":"数据","do":"读入炮集道数据，消除零漂直流分量，施加 10~80 Hz 零相位带通滤波以衰减面波。","effect":"消除有效频带外强干扰，统一各道有效波列波形基线。","trap":"使用最小相位滤波器会带来初至相位畸变，造成系统性走时偏早。"},{"name":"逐道 STA/LTA 能量比粗扫描","role":"算法","do":"以 8 点短窗与 55 点长窗滑动计算能量突变比值，锁定比值跃升点作为初至候选。","effect":"毫秒级并行完成单炮所有地震道的粗初至时间扫描定位。","trap":"噪声突发道上阈值设得过低会导致在有效信号到达前发生前驱假拾取。"},{"name":"AIC 局部极小值初至精修","role":"算法","do":"在粗拾取时间前后自适应时窗内拟合自回归赤池信息量曲线，搜索能量方差极小点。","effect":"彻底纠正传统 STA/LTA 窗长积分带来的 2~4ms 滞后偏差，对齐物理起跳点。","trap":"精修搜索窗宽不能过大，否则易跳跃到后续强能量同相轴波峰上。"},{"name":"炮集空间走时一致性回退","role":"空间","do":"沿偏移距检查初至走时曲线斜率，对偏离横向中位数趋势大于 3.5 点的离群道执行邻道回退。","effect":"成功纠正 3 条受前驱脉冲误触发的异常道，走时曲线恢复分段线性物理规律。","trap":"不可对隐伏断层或基底潜山引起的真实折射拐点进行过度平滑。"},{"name":"低置信度道排序与人工复核","role":"质控","do":"按比值峰锐度与回退调整幅度对每道赋置信度，高亮标红最低 10% 疑似道呈交人机核验。","effect":"全炮命中率达到 95.8%，平均绝对误差 MAE 控制在 1.8ms 内。","trap":"盲目全量人工重审会完全丧失自动化提效价值，精准推送才是核心。"}],"metrics":{"title":"流程分镜与验收指标","html":"<p>以下五步分镜展示从原始多源观测输入到最终工程可交付成果的完整演进过程与定量验收标准：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 220\" width=\"100%\" role=\"img\" aria-label=\"流程分镜与验收指标五步流程分镜\">\n  <rect width=\"760\" height=\"220\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <g transform=\"translate(12,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#12615a\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">01</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">道集滤波解编</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#e3ecf6\"/>\n    <path d=\"M22,83 L42,83 L50,55 L60,110 L70,83 L116,83\" stroke=\"#3a6ea5\" stroke-width=\"1.8\" fill=\"none\"/>\n    <text x=\"69\" y=\"118\" font-size=\"8.5\" fill=\"#3a6ea5\" text-anchor=\"middle\">单道滤波</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">读入 SEG-Y 炮集</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">10-80Hz 带通压制面波</text>\n    </g>\n<g transform=\"translate(161,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#3a6ea5\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">02</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">STA/LTA 粗扫</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#fbfaf7\" stroke=\"#c27a2c\"/>\n    <path d=\"M22,105 L60,105 L75,55 L85,100 L116,105\" stroke=\"#c27a2c\" stroke-width=\"2\" fill=\"none\"/>\n    <text x=\"69\" y=\"118\" font-size=\"8\" fill=\"#c27a2c\" text-anchor=\"middle\">能量比跃升峰</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">双窗滑动能量比</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">阈值 θ=3.2 初定起跳</text>\n    </g>\n<g transform=\"translate(310,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#6b5aa6\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">03</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">AIC 极小值精修</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#e3efec\"/>\n    <path d=\"M22,55 Q69,115 116,55\" stroke=\"#12615a\" stroke-width=\"2.2\" fill=\"none\"/>\n    <circle cx=\"69\" cy=\"85\" r=\"3.5\" fill=\"#12615a\"/>\n    <text x=\"69\" y=\"118\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"middle\">AIC 极小对齐</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">自回归赤池准则</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">方差极小修正滞后</text>\n    </g>\n<g transform=\"translate(459,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#c27a2c\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">04</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">空间一致性回退</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#fbfaf7\"/>\n    <line x1=\"22\" y1=\"105\" x2=\"116\" y2=\"55\" stroke=\"#12615a\" stroke-width=\"2.6\"/>\n    <circle cx=\"69\" cy=\"80\" r=\"4.5\" fill=\"#12615a\"/>\n    <text x=\"69\" y=\"118\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"middle\" font-weight=\"700\">走时曲线平滑</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">中位数横向走时约束</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">消除 #7/#14 前驱假警</text>\n    </g>\n<g transform=\"translate(608,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#2f7d5b\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">05</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">优先复核交付</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#fbfaf7\"/>\n    <rect x=\"30\" y=\"52\" width=\"78\" height=\"42\" rx=\"3\" fill=\"rgba(180,72,60,0.15)\" stroke=\"#b4483c\" stroke-width=\"1.5\"/>\n    <text x=\"69\" y=\"76\" font-size=\"9\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"middle\">抽检异常道</text>\n    <text x=\"69\" y=\"118\" font-size=\"8.5\" fill=\"#2f7d5b\" text-anchor=\"middle\" font-weight=\"700\">命中率 95.8%</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">仅复核 12.5% 异常道</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">输出静校正初至成果</text>\n    </g>\n</svg></div>\n<div class=\"figcap\"><b>图 6</b><span>五步初至波智能拾取流程分镜：从道集解编滤波（01）到 STA/LTA、AIC 精修与空间中位数约束及复核（05）。</span></div>\n<div class=\"figure\"><svg viewBox=\"0 0 760 185\" width=\"100%\" role=\"img\" aria-label=\"核心验收指标示意图\">\n  <rect width=\"760\" height=\"185\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <g transform=\"translate(14,14)\">\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"5\" rx=\"2\" fill=\"#12615a\"/>\n      <text x=\"12\" y=\"24\" font-size=\"11\" font-weight=\"700\" fill=\"#12615a\">1. 全炮初至命中率 (误差≤4ms)</text>\n      <rect x=\"12\" y=\"34\" width=\"210\" height=\"44\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n      <text x=\"117\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">Hit Rate = N(|Δt| ≤ 4ms) / N_total</text>\n      <text x=\"117\" y=\"70\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"600\">参考基准线：命中率 ≥ 90%</text>\n      <text x=\"12\" y=\"98\" font-size=\"9.5\" fill=\"#424a50\">• 相当于 2 个采样点严格工业交付容差</text>\n      <text x=\"12\" y=\"116\" font-size=\"9.5\" fill=\"#424a50\">• 单道原始命中率仅 79.2% (受前驱干扰)</text>\n      <text x=\"12\" y=\"140\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：全炮命中率 = 95.8%</text>\n    </g>\n<g transform=\"translate(263,14)\">\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"5\" rx=\"2\" fill=\"#3a6ea5\"/>\n      <text x=\"12\" y=\"24\" font-size=\"11\" font-weight=\"700\" fill=\"#3a6ea5\">2. 平均绝对时间误差 MAE</text>\n      <rect x=\"12\" y=\"34\" width=\"210\" height=\"44\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n      <text x=\"117\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">MAE = (1/N) · Σ |t_pick - t_true|</text>\n      <text x=\"117\" y=\"70\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#3a6ea5\" font-weight=\"600\">参考基准线：MAE ≤ 3.0 ms</text>\n      <text x=\"12\" y=\"98\" font-size=\"9.5\" fill=\"#424a50\">• 未施加空间约束前原始 MAE 为 14.6 ms</text>\n      <text x=\"12\" y=\"116\" font-size=\"9.5\" fill=\"#424a50\">• AIC 精修彻底消除了能量积分正偏</text>\n      <text x=\"12\" y=\"140\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：MAE = 1.8 ms</text>\n    </g>\n<g transform=\"translate(512,14)\">\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"5\" rx=\"2\" fill=\"#c27a2c\"/>\n      <text x=\"12\" y=\"24\" font-size=\"11\" font-weight=\"700\" fill=\"#c27a2c\">3. 需人工抽检道占比</text>\n      <rect x=\"12\" y=\"34\" width=\"210\" height=\"44\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n      <text x=\"117\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">QC Ratio = N_flagged / N_total</text>\n      <text x=\"117\" y=\"70\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#c27a2c\" font-weight=\"600\">控制线：≤ 20% (保证提效)</text>\n      <text x=\"12\" y=\"98\" font-size=\"9.5\" fill=\"#424a50\">• 系统自动标红 3 条受前驱脉冲冲击道</text>\n      <text x=\"12\" y=\"116\" font-size=\"9.5\" fill=\"#424a50\">• 处理员仅需审阅 12.5% 道即可放行</text>\n      <text x=\"12\" y=\"140\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：仅需复核 3/24 道 (12.5%)</text>\n    </g>\n</svg></div>\n<div class=\"figcap\"><b>图 7</b><span>工程交付三大定量验收标准：全炮命中率（误差≤4ms）、平均绝对误差 MAE 与人工抽检道占比。</span></div>"},"fails":[{"name":"前驱脉冲提前触发","why":"电缆打火或近炮点震源脉冲提前出现，致使能量比在真实初至前冲过阈值。"},{"name":"远道弱信号漏拾取","why":"几何扩散严重时远道弱初至能量比始终低于触发阈值，造成整道拾取丢失。"},{"name":"空间平滑抹除地质断阶","why":"横向约束窗口过宽，把基底断层引起的地质走时跳变当成噪声平滑拉平。"}]},"demo":{"mode":"auto","html":"demo/index.html","label":"可运行示范","intro":"","height":980}}},"files":[{"name":"demo/index.html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>地震炮集初至波自动拾取与空间一致性约束</title>\n<link rel=\"stylesheet\" href=\"demo.css\">\n</head>\n<body>\n<div class=\"app\">\n  <!-- 顶栏：仅标题与实时状态胶囊，无副标题 -->\n  <header class=\"topbar\">\n    <h1>地震炮集初至波自动拾取与空间一致性约束</h1>\n    <div class=\"sp\"></div>\n    <span class=\"pill acc\" id=\"pill-vel\"><i></i><span id=\"pill-vel-txt\">反演 v₀=750 m/s · v₁=2100 m/s</span></span>\n    <span class=\"pill ok\" id=\"pill-status\"><i></i><span id=\"pill-status-txt\">命中率 95.8% · 空间约束已生效</span></span>\n  </header>\n\n  <!-- 5 步流程步进条 -->\n  <nav class=\"stepper\" id=\"stepper\" aria-label=\"案例流程步骤\">\n    <button type=\"button\" data-step=\"0\" class=\"done\">\n      <span class=\"n\">STEP 01</span>\n      <span class=\"t\">道集解编与带通滤波预处理</span>\n    </button>\n    <button type=\"button\" data-step=\"1\" class=\"done\">\n      <span class=\"n\">STEP 02</span>\n      <span class=\"t\">逐道 STA/LTA 与深度学习概率扫描</span>\n    </button>\n    <button type=\"button\" data-step=\"2\" class=\"done\">\n      <span class=\"n\">STEP 03</span>\n      <span class=\"t\">AIC 局部极小值初至精修</span>\n    </button>\n    <button type=\"button\" data-step=\"3\" class=\"done\">\n      <span class=\"n\">STEP 04</span>\n      <span class=\"t\">炮集走时曲线空间一致性回退</span>\n    </button>\n    <button type=\"button\" data-step=\"4\" class=\"on\">\n      <span class=\"n\">STEP 05</span>\n      <span class=\"t\">低置信度道排序与人工复核验收</span>\n    </button>\n  </nav>\n\n  <!-- 主工作台 -->\n  <div class=\"bench\">\n    <!-- 左侧控制栏 -->\n    <aside class=\"rail\">\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>拾取算法与特征算子</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">单道算子</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"seg seg-col\" id=\"method-seg\">\n            <button type=\"button\" data-method=\"stalta\">\n              <span>STA/LTA 能量比</span>\n              <small>阈值触发</small>\n            </button>\n            <button type=\"button\" data-method=\"aic\" class=\"on\">\n              <span>STA/LTA + AIC 精修</span>\n              <small>起跳极小值</small>\n            </button>\n            <button type=\"button\" data-method=\"unet\">\n              <span>1D 卷积概率峰</span>\n              <small>PhaseNet 风格</small>\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>观测噪声与窗长阈值</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">实时重算</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>背景与突发噪声水平</span>\n              <output id=\"out-noise\">1.10</output>\n            </div>\n            <input type=\"range\" id=\"sl-noise\" min=\"0.2\" max=\"2.8\" step=\"0.05\" value=\"1.10\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>触发阈值 (Threshold)</span>\n              <output id=\"out-thr\">3.2</output>\n            </div>\n            <input type=\"range\" id=\"sl-thr\" min=\"1.5\" max=\"7.5\" step=\"0.1\" value=\"3.2\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>短窗长度 STA (采样点)</span>\n              <output id=\"out-sta\">8 点 (16ms)</output>\n            </div>\n            <input type=\"range\" id=\"sl-sta\" min=\"4\" max=\"20\" step=\"1\" value=\"8\">\n          </div>\n\n          <div class=\"divider\"></div>\n\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-spatial\" checked>\n            <span>启用炮集空间走时一致性约束</span>\n          </label>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-va\" checked>\n            <span>叠加正半周变面积填充 (Wiggle+VA)</span>\n          </label>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-qc\" checked>\n            <span>高亮需人工复核的低置信度道</span>\n          </label>\n\n          <div class=\"btn-row\">\n            <button type=\"button\" class=\"btn primary\" id=\"btn-demo\">异常噪声冲击</button>\n            <button type=\"button\" class=\"btn\" id=\"btn-reset\">重置标准工况</button>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>单道显微镜选道 (#1–#24)</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">点击切换</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"small muted\">橙色为突发脉冲干扰道 (#7/#14/#21)，点击道号或直接在右侧剖面点击波形：</div>\n          <div class=\"trace-pills\" id=\"trace-pills\"></div>\n        </div>\n      </div>\n    </aside>\n\n    <!-- 右侧主舞台 -->\n    <main class=\"stage\">\n      <!-- 主视图：24 道单炮变面积波形剖面 -->\n      <section class=\"view\" id=\"shot-view\">\n        <div class=\"view-h\">\n          <span>单炮 24 道地震记录剖面 (Shot Gather · 偏移距 50m–1200m · 采样率 Δt=2ms)</span>\n          <span class=\"sp\"></span>\n          <span class=\"badge-mini acc\" id=\"step-badge\">当前展示：全流程走时约束与复核标记</span>\n          <span class=\"badge-mini warn\" id=\"sel-badge\">当前检视：第 #14 道 (x=700m)</span>\n        </div>\n        <svg id=\"svg-shot\" class=\"shot-svg\" viewBox=\"0 0 860 390\" role=\"img\" aria-label=\"24道地震单炮道集与初至波走时曲线\"></svg>\n        <div class=\"tip\" id=\"shot-tip\"></div>\n        <div class=\"view-f\">\n          <div class=\"legend\">\n            <span><i class=\"dash\" style=\"color:#2f7d5b\"></i>真值初至走时 (v₀=750, v₁=2100 m/s)</span>\n            <span><i class=\"line\" style=\"background:#c27a2c\"></i>单道原始拾取点 (含脉冲误触发)</span>\n            <span><i class=\"line\" style=\"background:#12615a;height:3px\"></i>空间一致性约束走时曲线</span>\n            <span><i style=\"background:rgba(180,72,60,.22);border:1px solid #b4483c\"></i>低置信度待人工复核道</span>\n            <span><i style=\"background:rgba(58,110,165,.18);border:1px dashed #3a6ea5\"></i>面波低频干扰锥 (Ground Roll)</span>\n          </div>\n        </div>\n      </section>\n\n      <!-- 4 个实时 KPI -->\n      <section class=\"kpis\">\n        <div class=\"kpi ok\" id=\"kpi-hit\">\n          <div class=\"k\">全炮命中率 (误差 ≤4ms)</div>\n          <div class=\"v\"><span id=\"val-hit\">95.8</span><small>%</small></div>\n          <div class=\"d\" id=\"sub-hit\">单道原始命中率 79.2%</div>\n        </div>\n        <div class=\"kpi acc\" id=\"kpi-mae\">\n          <div class=\"k\">平均绝对误差 MAE</div>\n          <div class=\"v\"><span id=\"val-mae\">1.8</span><small>ms</small></div>\n          <div class=\"d\" id=\"sub-mae\">约束前原始误差 14.6 ms</div>\n        </div>\n        <div class=\"kpi warn\" id=\"kpi-fix\">\n          <div class=\"k\">一致性约束纠偏道数</div>\n          <div class=\"v\"><span id=\"val-fix\">3</span><small>/ 24 道</small></div>\n          <div class=\"d\" id=\"sub-fix\">成功拦截前驱噪声尖峰假拾取</div>\n        </div>\n        <div class=\"kpi ok\" id=\"kpi-qc\">\n          <div class=\"k\">需人工复核道占比</div>\n          <div class=\"v\"><span id=\"val-qc\">12.5</span><small>%</small></div>\n          <div class=\"d\" id=\"sub-qc\">仅需人工质控 3 道 (节省 87.5% 工时)</div>\n        </div>\n      </section>\n\n      <!-- 双栏辅助分析图 -->\n      <section class=\"grid2\">\n        <!-- 左：当前选中道的单道显微镜 -->\n        <div class=\"view\">\n          <div class=\"view-h\">\n            <span id=\"micro-title\">第 #14 道 (偏移距 700m) 波形 + STA/LTA + AIC 局部精修双联图</span>\n            <span class=\"sp\"></span>\n            <span class=\"hint\">点击主剖面任意道切换</span>\n          </div>\n          <svg id=\"svg-micro\" viewBox=\"0 0 430 250\" role=\"img\" aria-label=\"单道波形与STA/LTA及AIC局部精修图\"></svg>\n          <div class=\"view-f\">\n            <div class=\"legend\">\n              <span><i class=\"line\" style=\"background:#3a6ea5\"></i>滤波波形 x(t)</span>\n              <span><i class=\"line\" style=\"background:#c27a2c\"></i>STA/LTA 或概率曲线</span>\n              <span><i class=\"line\" style=\"background:#6b5aa6\"></i>AIC 准则曲线 (极小值精修)</span>\n              <span><i class=\"line\" style=\"background:#12615a\"></i>最终采用初至</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- 右：偏移距-走时折线拟合反演表层速度与逐道误差对比 -->\n        <div class=\"view\">\n          <div class=\"view-h\">\n            <span>折射走时反演表层速度 (v₀, v₁, h₀) 与约束前后逐道误差 (ms)</span>\n            <span class=\"sp\"></span>\n            <span class=\"hint\" id=\"vel-fit-hint\">h₀ = 109.2 m</span>\n          </div>\n          <svg id=\"svg-refrac\" viewBox=\"0 0 430 250\" role=\"img\" aria-label=\"偏移距走时折线反演与逐道误差对比图\"></svg>\n          <div class=\"view-f\">\n            <div class=\"legend\">\n              <span><i class=\"line\" style=\"background:#c27a2c\"></i>约束前单道误差 |Δt|</span>\n              <span><i class=\"line\" style=\"background:#12615a\"></i>空间约束后误差 |Δt|</span>\n              <span><i class=\"dash\" style=\"color:#2f7d5b\"></i>±4ms (2采样点) 验收容差带</span>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- 动态专业解读 -->\n      <section class=\"insight\" id=\"insight-box\">\n        <div class=\"tag\" id=\"insight-tag\">物探质控解读</div>\n        <div id=\"insight-text\"></div>\n      </section>\n    </main>\n  </div>\n</div>\n<script src=\"demo.js\"></script>\n</body>\n</html>\n","enc":"text","size":10008},{"name":"demo/demo.css","data":"/* =========================================================\n   Demo Kit · 案例示范统一样式（每个案例的 demo.css 顶部整段复制本文件）\n   ---------------------------------------------------------\n   运行在沙箱 iframe 里，与主站完全隔离；只用系统字体，离线可用。\n   结构：.app > .topbar + .stepper? + .bench(.rail + .stage) + .kpis + .grid2 + .insight\n   ========================================================= */\n:root{\n  --paper:#f7f5f0; --paper-2:#f0ede5; --surface:#ffffff;\n  --ink:#15191c; --ink-2:#424a50; --ink-3:#737c83; --ink-4:#a3aab0;\n  --line:#e7e3da; --line-2:#d9d4c8;\n  --accent:#12615a; --accent-2:#1d7f75; --accent-l:#e3efec;\n  --amber:#c27a2c; --amber-l:#f7ecdd;\n  --red:#b4483c;  --red-l:#f6e3df;\n  --green:#2f7d5b; --green-l:#e2f0e8;\n  --blue:#3a6ea5; --blue-l:#e3ecf6;\n  --violet:#6b5aa6; --violet-l:#ebe7f5;\n  --sans:\"PingFang SC\",\"HarmonyOS Sans SC\",\"Microsoft YaHei\",\"Noto Sans SC\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --mono:\"JetBrains Mono\",\"Cascadia Code\",\"SF Mono\",Consolas,ui-monospace,monospace;\n  --r:12px; --r-s:8px;\n  --sh:0 1px 2px rgba(21,25,28,.04),0 6px 24px -12px rgba(21,25,28,.12);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--paper);color:var(--ink)}\nbody{font-family:var(--sans);font-size:13px;line-height:1.7;-webkit-font-smoothing:antialiased;padding:20px 22px 26px}\nb,strong{font-weight:650}\n.mono{font-family:var(--mono)}\n.app{max-width:1160px;margin:0 auto}\n\n/* ---------- 顶栏：只有标题 + 右侧状态胶囊，不放副标题 ---------- */\n.topbar{display:flex;align-items:center;gap:14px;padding-bottom:14px;margin-bottom:16px;border-bottom:1px solid var(--line)}\n.topbar h1{font-size:19px;line-height:1.3;margin:0;letter-spacing:-.01em;font-weight:700}\n.topbar .sp{flex:1}\n.pill{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px;border-radius:999px;font-size:11.5px;\n  border:1px solid var(--line-2);background:var(--surface);color:var(--ink-2);white-space:nowrap}\n.pill i{width:7px;height:7px;border-radius:50%;background:currentColor;display:inline-block}\n.pill.ok{color:var(--green);border-color:rgba(47,125,91,.28);background:var(--green-l)}\n.pill.warn{color:var(--amber);border-color:rgba(194,122,44,.3);background:var(--amber-l)}\n.pill.bad{color:var(--red);border-color:rgba(180,72,60,.28);background:var(--red-l)}\n.pill.acc{color:var(--accent);border-color:rgba(18,97,90,.25);background:var(--accent-l)}\n\n/* ---------- 流程步进条：与「案例流程」tab 的步骤一一对应 ---------- */\n.stepper{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:0;margin:0 0 16px;\n  background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.stepper button{all:unset;cursor:pointer;position:relative;padding:11px 14px 11px 16px;border-right:1px solid var(--line);\n  display:flex;flex-direction:column;gap:2px;transition:background .18s}\n.stepper button:last-child{border-right:0}\n.stepper button .n{font-family:var(--mono);font-size:10.5px;color:var(--ink-4);letter-spacing:.06em}\n.stepper button .t{font-size:12.5px;font-weight:600;color:var(--ink-2)}\n.stepper button:hover{background:var(--paper)}\n.stepper button.on{background:var(--accent-l)}\n.stepper button.on .n{color:var(--accent)}\n.stepper button.on .t{color:var(--accent)}\n.stepper button.on::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--accent)}\n.stepper button.done .n::after{content:\" ✓\";color:var(--green)}\n\n/* ---------- 工作台：左控制栏 + 右主画布 ---------- */\n.bench{display:grid;grid-template-columns:270px 1fr;gap:16px;align-items:start}\n.rail{display:flex;flex-direction:column;gap:12px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh)}\n.card-h{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line);\n  font-size:12px;font-weight:650;color:var(--ink-2)}\n.card-h .sp{flex:1}\n.card-h .hint{font-weight:400;color:var(--ink-4);font-size:11px}\n.card-b{padding:12px 14px}\n.stage{min-width:0;display:flex;flex-direction:column;gap:16px}\n.view{position:relative;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh);overflow:hidden}\n.view canvas,.view svg{display:block;width:100%;height:auto}\n.view-h{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line);font-size:12px;font-weight:650;color:var(--ink-2)}\n.view-h .sp{flex:1}\n.view-f{display:flex;flex-wrap:wrap;gap:6px 16px;padding:9px 14px;border-top:1px solid var(--line);font-size:11.5px;color:var(--ink-3)}\n\n/* ---------- 控件 ---------- */\n.ctl{display:flex;flex-direction:column;gap:5px;margin-bottom:12px}\n.ctl:last-child{margin-bottom:0}\n.ctl-l{display:flex;align-items:baseline;justify-content:space-between;font-size:12px;color:var(--ink-2)}\n.ctl-l output,.ctl-l .v{font-family:var(--mono);font-size:12px;color:var(--accent);font-weight:600}\ninput[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:20px;background:transparent;margin:0}\ninput[type=range]::-webkit-slider-runnable-track{height:4px;border-radius:4px;background:linear-gradient(90deg,var(--accent) var(--p,50%),var(--line) var(--p,50%))}\ninput[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:16px;border-radius:50%;margin-top:-6px;\n  background:#fff;border:2px solid var(--accent);box-shadow:0 1px 4px rgba(0,0,0,.15)}\ninput[type=range]::-moz-range-track{height:4px;border-radius:4px;background:var(--line)}\ninput[type=range]::-moz-range-progress{height:4px;border-radius:4px;background:var(--accent)}\ninput[type=range]::-moz-range-thumb{width:14px;height:14px;border-radius:50%;background:#fff;border:2px solid var(--accent)}\n.seg{display:flex;background:var(--paper-2);border-radius:9px;padding:3px;gap:3px}\n.seg button{all:unset;flex:1;text-align:center;cursor:pointer;font-size:12px;padding:5px 6px;border-radius:7px;color:var(--ink-3);transition:all .15s}\n.seg button:hover{color:var(--ink)}\n.seg button.on{background:var(--surface);color:var(--ink);font-weight:600;box-shadow:0 1px 3px rgba(0,0,0,.08)}\n.btn{all:unset;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:32px;padding:0 14px;\n  border-radius:9px;font-size:12.5px;font-weight:600;border:1px solid var(--line-2);background:var(--surface);color:var(--ink);transition:all .15s}\n.btn:hover{border-color:var(--ink-3)}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}\n.btn.primary:hover{background:var(--accent-2)}\n.btn.block{display:flex;width:100%;box-sizing:border-box}\n.btn:disabled,.btn.disabled{opacity:.45;pointer-events:none}\n.check{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-2);cursor:pointer;user-select:none;margin:4px 0}\n.check input{accent-color:var(--accent);width:14px;height:14px;margin:0}\n\n/* ---------- 指标条 ---------- */\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:0;background:var(--surface);\n  border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.kpi{padding:12px 16px;border-right:1px solid var(--line)}\n.kpi:last-child{border-right:0}\n.kpi .k{font-size:11px;color:var(--ink-3);letter-spacing:.02em}\n.kpi .v{font-family:var(--mono);font-size:22px;font-weight:600;line-height:1.25;margin-top:3px;letter-spacing:-.02em}\n.kpi .v small{font-size:12px;color:var(--ink-3);font-weight:500;margin-left:3px}\n.kpi .d{font-size:11px;color:var(--ink-4);margin-top:2px}\n.kpi.ok .v{color:var(--green)} .kpi.bad .v{color:var(--red)} .kpi.warn .v{color:var(--amber)} .kpi.acc .v{color:var(--accent)}\n\n/* ---------- 栅格 ---------- */\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\n\n/* ---------- 图例 ---------- */\n.legend{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:11.5px;color:var(--ink-3)}\n.legend span{display:inline-flex;align-items:center;gap:6px}\n.legend i{width:10px;height:10px;border-radius:3px;display:inline-block}\n.legend i.line{height:2px;width:14px;border-radius:0}\n.legend i.dash{height:0;width:14px;border-top:2px dashed currentColor;border-radius:0}\n\n/* ---------- 解读：随参数变化的动态说明 ---------- */\n.insight{display:grid;grid-template-columns:auto 1fr;gap:12px;align-items:start;padding:13px 16px;border-radius:var(--r);\n  background:var(--surface);border:1px solid var(--line);border-left:3px solid var(--accent);box-shadow:var(--sh);font-size:12.5px;color:var(--ink-2);line-height:1.8}\n.insight .tag{font-size:11px;font-weight:700;color:var(--accent);letter-spacing:.08em;padding-top:2px;white-space:nowrap}\n.insight.warn{border-left-color:var(--amber)} .insight.warn .tag{color:var(--amber)}\n.insight.bad{border-left-color:var(--red)} .insight.bad .tag{color:var(--red)}\n.insight b{color:var(--ink)}\n\n/* ---------- 表格 ---------- */\ntable.t{width:100%;border-collapse:collapse;font-size:12px}\ntable.t th{text-align:left;font-weight:600;color:var(--ink-3);font-size:11px;padding:7px 10px;border-bottom:1px solid var(--line);background:var(--paper)}\ntable.t td{padding:7px 10px;border-bottom:1px solid var(--line);color:var(--ink-2)}\ntable.t td.num{font-family:var(--mono);text-align:right}\ntable.t tr:last-child td{border-bottom:0}\n\n/* ---------- 浮动提示 ---------- */\n.tip{position:absolute;pointer-events:none;z-index:5;background:rgba(21,25,28,.92);color:#fff;font-size:11.5px;line-height:1.6;\n  padding:7px 10px;border-radius:7px;white-space:nowrap;transform:translate(-50%,calc(-100% - 10px));opacity:0;transition:opacity .12s}\n.tip.on{opacity:1}\n.tip b{color:#fff}\n\n/* ---------- 小工具 ---------- */\n.muted{color:var(--ink-3)} .small{font-size:11.5px}\n.row{display:flex;align-items:center;gap:8px}\n.divider{height:1px;background:var(--line);margin:12px 0}\n.bar{height:6px;border-radius:6px;background:var(--paper-2);overflow:hidden}\n.bar i{display:block;height:100%;border-radius:6px;background:var(--accent);transition:width .3s}\n.fade-in{animation:fi .35s ease both}\n@keyframes fi{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}\n\n@media (max-width:860px){\n  .bench{grid-template-columns:1fr}\n  .grid2,.grid3{grid-template-columns:1fr}\n  .stepper{grid-auto-flow:row}\n  .stepper button{border-right:0;border-bottom:1px solid var(--line)}\n}\n/* ===================== Demo Kit 结束 ===================== */\n\n/* ---------- 地震炮集初至波自动拾取专属样式 ---------- */\n.seg-col{flex-direction:column}\n.seg-col button{text-align:left;padding:6px 10px;display:flex;align-items:center;justify-content:space-between}\n.seg-col button small{font-family:var(--mono);font-size:10.5px;color:var(--ink-4)}\n.seg-col button.on small{color:var(--accent)}\n\n.trace-pills{display:grid;grid-template-columns:repeat(6,1fr);gap:4px;margin-top:6px}\n.tr-btn{all:unset;cursor:pointer;font-family:var(--mono);font-size:11px;text-align:center;padding:3px 0;\n  border-radius:5px;border:1px solid var(--line);background:var(--paper);color:var(--ink-2);transition:all .12s}\n.tr-btn:hover{border-color:var(--ink-3)}\n.tr-btn.on{background:var(--accent);border-color:var(--accent);color:#fff;font-weight:600}\n.tr-btn.fix{border-color:rgba(194,122,44,.45);background:var(--amber-l);color:var(--amber)}\n.tr-btn.fix.on{background:var(--amber);color:#fff}\n.tr-btn.bad{border-color:rgba(180,72,60,.45);background:var(--red-l);color:var(--red)}\n.tr-btn.bad.on{background:var(--red);color:#fff}\n\n.shot-svg{cursor:crosshair;user-select:none}\n.btn-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px}\n.badge-mini{display:inline-flex;align-items:center;gap:4px;padding:1px 7px;border-radius:99px;font-size:11px;font-family:var(--mono);background:var(--paper-2);color:var(--ink-2)}\n.badge-mini.acc{background:var(--accent-l);color:var(--accent);font-weight:600}\n.badge-mini.warn{background:var(--amber-l);color:var(--amber);font-weight:600}\n","enc":"text","size":12059},{"name":"demo/demo.js","data":"// ============================================================================\n// 物探 · 初至波自动拾取（seismic-firstbreak-pick）交互式工作台逻辑\n// 24道单炮记录 Wiggle+VA 变面积剖面 + STA/LTA + AIC + 空间一致性约束\n// ============================================================================\n(function () {\n  'use strict';\n\n  const N_TRACES = 24;\n  const N_SAMPLES = 360;\n  const DT = 2; // 采样间隔 2 ms，总时长 720 ms\n  const V0_TRUE = 750;  // 风化层速度 m/s\n  const V1_TRUE = 2100; // 高速折射层速度 m/s\n  const T_INT_TRUE = 260; // 折射截距时间 ms\n  const LTA_WIN = 55;\n\n  const state = {\n    step: 4,\n    method: 'aic', // 'stalta' | 'aic' | 'unet'\n    noise: 1.10,\n    thr: 3.2,\n    sta: 8,\n    spatial: true,\n    showVA: true,\n    showQC: true,\n    selTrace: 13 // 0-indexed -> 第 #14 道\n  };\n\n  function mulberry32(a) {\n    return function () {\n      a |= 0; a = (a + 0x6D2B79F5) | 0;\n      let t = Math.imul(a ^ (a >>> 15), 1 | a);\n      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n    };\n  }\n\n  // 预生成 24 道的固定随机噪声基底与前驱尖峰干扰（#7, #14, #21 索引为 6, 13, 20）\n  const baseTraces = [];\n  const SPURIOUS_IDS = [6, 13, 20];\n\n  (function initSyntheticGather() {\n    for (let tr = 0; tr < N_TRACES; tr++) {\n      const rng = mulberry32(20261001 + tr * 97);\n      const offset = (tr + 1) * 50; // 50m .. 1200m\n      const tDirect = (offset / V0_TRUE) * 1000;\n      const tRefrac = T_INT_TRUE + (offset / V1_TRUE) * 1000;\n      const tTrueMs = Math.min(tDirect, tRefrac);\n      const idxTrue = Math.round(tTrueMs / DT);\n\n      const clean = new Float64Array(N_SAMPLES);\n      const noise = new Float64Array(N_SAMPLES);\n      const spike = new Float64Array(N_SAMPLES);\n\n      // 远偏移距几何扩散衰减\n      const att = Math.pow(offset / 150, -0.32);\n\n      for (let i = 0; i < N_SAMPLES; i++) {\n        noise[i] = (rng() + rng() + rng() - 1.5) * 0.52;\n        if (i >= idxTrue) {\n          const d = i - idxTrue;\n          // 雷克子波主脉冲 + 后续尾波\n          const env = Math.exp(-d / 32) * att;\n          clean[i] = env * (Math.sin((d / 11) * Math.PI * 2) * 2.3 + Math.sin((d / 22) * Math.PI * 2) * 0.8);\n        }\n        // 低频面波干扰锥（Ground Roll，速度约 340 m/s）\n        const idxGR = Math.round(((offset / 340) * 1000 + 80) / DT);\n        if (i >= idxGR && i < idxGR + 70) {\n          const dg = i - idxGR;\n          clean[i] += Math.exp(-dg / 40) * Math.sin((dg / 24) * Math.PI * 2) * 0.9;\n        }\n      }\n\n      // 在 #7, #14, #21 初至前 38–52 个采样点注入前驱野值脉冲\n      const isSpurious = SPURIOUS_IDS.includes(tr);\n      const spikeIdx = Math.max(LTA_WIN + 18, idxTrue - (tr === 13 ? 44 : 38));\n      if (isSpurious) {\n        for (let k = -4; k <= 6; k++) {\n          if (spikeIdx + k >= 0 && spikeIdx + k < N_SAMPLES) {\n            spike[spikeIdx + k] = Math.exp(-Math.abs(k) / 2.2) * Math.sin(k * 1.3) * 2.35;\n          }\n        }\n      }\n\n      baseTraces.push({ tr, no: tr + 1, offset, tTrueMs, idxTrue, clean, noise, spike, isSpurious, spikeIdx });\n    }\n  })();\n\n  // 计算单道 STA/LTA、AIC 与最终拾取点\n  function computeGather() {\n    const STA = state.sta;\n    const LTA = LTA_WIN;\n    const thr = state.thr;\n    const nl = state.noise;\n\n    const results = baseTraces.map(bt => {\n      const wave = new Float64Array(N_SAMPLES);\n      for (let i = 0; i < N_SAMPLES; i++) {\n        wave[i] = bt.clean[i] + bt.noise[i] * nl * 0.45 + bt.spike[i] * (nl * 0.85);\n      }\n\n      // 1. STA/LTA 能量比与 1D-UNet 概率曲线\n      const ratio = new Float64Array(N_SAMPLES);\n      const prob = new Float64Array(N_SAMPLES);\n      let maxRatio = 1;\n      for (let i = STA + LTA; i < N_SAMPLES; i++) {\n        let se = 0, le = 0;\n        for (let k = i - STA + 1; k <= i; k++) se += wave[k] * wave[k];\n        for (let k = i - STA - LTA + 1; k <= i - STA; k++) le += wave[k] * wave[k];\n        const r = (se / STA) / (le / LTA + 1e-4);\n        ratio[i] = Math.min(14, r);\n        if (ratio[i] > maxRatio) maxRatio = ratio[i];\n      }\n\n      // 模拟 1D 卷积网络对初至起跳相位的响应概率（抗单点脉冲能力更强）\n      for (let i = 0; i < N_SAMPLES; i++) {\n        const dTrue = (i - bt.idxTrue) / (3.2 + nl * 1.1);\n        let p = Math.exp(-0.5 * dTrue * dTrue) * Math.min(9.5, Math.max(2.2, 8.8 - nl * 1.5));\n        if (bt.isSpurious) {\n          const dSpk = (i - bt.spikeIdx) / 2.8;\n          p += Math.exp(-0.5 * dSpk * dSpk) * (nl * 1.65);\n        }\n        prob[i] = p;\n      }\n\n      // 2. 候选粗拾取\n      let rawPick = -1;\n      const scanCurve = state.method === 'unet' ? prob : ratio;\n      for (let i = STA + LTA; i < N_SAMPLES - 10; i++) {\n        if (scanCurve[i] >= thr) { rawPick = i; break; }\n      }\n\n      // 3. AIC 局部极小值精修（在粗拾取前后 [-16, +8] 窗内寻找方差突变极小点）\n      const aic = new Float64Array(N_SAMPLES);\n      let aicPick = rawPick;\n      if (rawPick > 25) {\n        const w0 = Math.max(20, rawPick - 18);\n        const w1 = Math.min(N_SAMPLES - 15, rawPick + 10);\n        let minAic = Infinity, bestK = rawPick;\n        for (let k = w0; k <= w1; k++) {\n          let v1 = 1e-6, v2 = 1e-6;\n          for (let j = w0 - 10; j < k; j++) v1 += wave[j] * wave[j];\n          for (let j = k; j <= w1 + 10; j++) v2 += wave[j] * wave[j];\n          v1 /= Math.max(1, k - (w0 - 10));\n          v2 /= Math.max(1, (w1 + 10) - k + 1);\n          const val = (k - w0) * Math.log(v1) + (w1 - k) * Math.log(v2);\n          aic[k] = val;\n          if (val < minAic) { minAic = val; bestK = k; }\n        }\n        // 归一化便于显示\n        for (let i = 0; i < N_SAMPLES; i++) {\n          if (i < w0 || i > w1) aic[i] = aic[w0] || 0;\n        }\n        if (state.method === 'aic' && state.step >= 2) {\n          aicPick = bestK;\n        }\n      }\n\n      // 单道特征拾取（未加空间约束）\n      let singlePick = state.method === 'aic' ? aicPick : rawPick;\n      if (state.method === 'stalta' && singlePick > 0) {\n        // 纯 STA/LTA 往往比真正初至起跳滞后 2~3 个采样点\n        singlePick = Math.min(N_SAMPLES - 1, singlePick + Math.round(STA * 0.28));\n      }\n\n      return {\n        bt,\n        wave,\n        ratio: scanCurve,\n        aic,\n        singlePick,\n        finalPick: singlePick,\n        corrected: false,\n        lowConf: false\n      };\n    });\n\n    // 4. 炮集空间走时一致性约束（中位数趋势滤波回退离群道）\n    results.forEach((r, idx) => {\n      const neighbors = [];\n      for (let d = -2; d <= 2; d++) {\n        if (d === 0) continue;\n        const nb = results[idx + d];\n        if (nb && nb.singlePick > 0) {\n          // 按偏移距线性折算到当前道\n          const slope = idx < 6 ? (50 / V0_TRUE * 1000 / DT) : (50 / V1_TRUE * 1000 / DT);\n          neighbors.push(nb.singlePick - d * slope);\n        }\n      }\n      neighbors.sort((a, b) => a - b);\n      const med = neighbors.length ? neighbors[Math.floor(neighbors.length / 2)] : r.bt.idxTrue;\n      const dev = r.singlePick < 0 ? 999 : Math.abs(r.singlePick - med);\n\n      if (dev > 3.5) {\n        r.lowConf = true;\n        if (state.spatial && state.step >= 3) {\n          r.finalPick = Math.round(med);\n          r.corrected = true;\n        }\n      }\n    });\n\n    return results;\n  }\n\n  // 渲染左侧 #1–#24 选道按钮\n  function renderTracePills(results) {\n    const box = document.getElementById('trace-pills');\n    if (!box) return;\n    box.innerHTML = results.map((r, i) => {\n      const cls = [\n        'trace-pill',\n        i === state.selTrace ? 'on' : '',\n        r.bt.isSpurious ? 'noisy' : ''\n      ].filter(Boolean).join(' ');\n      return `<button type=\"button\" class=\"${cls}\" data-tr=\"${i}\">#${r.bt.no}</button>`;\n    }).join('');\n    box.querySelectorAll('.trace-pill').forEach(btn => {\n      btn.addEventListener('click', () => {\n        state.selTrace = +btn.dataset.tr;\n        updateAll();\n      });\n    });\n  }\n\n  // 渲染主视图：24 道单炮 Wiggle + 变面积剖面\n  function renderShotGather(results) {\n    const svg = document.getElementById('svg-shot');\n    if (!svg) return;\n    const W = 860, H = 390;\n    const L = 52, R = 24, T = 26, B = 28;\n    const plotW = W - L - R, plotH = H - T - B;\n    const dx = plotW / N_TRACES;\n    const xOf = tr => L + (tr + 0.5) * dx;\n    const yOf = idx => T + (idx / (N_SAMPLES - 1)) * plotH;\n\n    let h = `<rect x=\"${L}\" y=\"${T}\" width=\"${plotW}\" height=\"${plotH}\" fill=\"#fcfaf5\" stroke=\"#ded8ca\"/>`;\n\n    // 时间网格线 (0..700 ms)\n    for (let ms = 0; ms <= 700; ms += 100) {\n      const y = yOf(ms / DT);\n      h += `<line x1=\"${L}\" y1=\"${y.toFixed(1)}\" x2=\"${W - R}\" y2=\"${y.toFixed(1)}\" stroke=\"#ece7db\" stroke-width=\"1\"/>`;\n      h += `<text x=\"${L - 6}\" y=\"${(y + 3).toFixed(1)}\" font-size=\"9.5\" font-family=\"ui-monospace,monospace\" fill=\"#6b747c\" text-anchor=\"end\">${ms}ms</text>`;\n    }\n\n    // 面波低频干扰锥示意背景\n    const grX1 = xOf(0), grY1 = yOf(110);\n    const grX2 = xOf(10), grY2 = yOf(355);\n    const grX3 = xOf(4), grY3 = yOf(355);\n    h += `<polygon points=\"${grX1},${grY1} ${grX2},${grY2} ${grX3},${grY3}\" fill=\"rgba(58,110,165,0.09)\" stroke=\"#3a6ea5\" stroke-width=\"1\" stroke-dasharray=\"4 3\"/>`;\n\n    // 逐道绘制高亮带与 Wiggle+VA 波形\n    results.forEach((r, i) => {\n      const cx = xOf(i);\n      const isSel = i === state.selTrace;\n\n      // 低置信度复核道红底高亮\n      if (state.showQC && r.lowConf && state.step >= 3) {\n        h += `<rect x=\"${(cx - dx * 0.46).toFixed(1)}\" y=\"${T}\" width=\"${(dx * 0.92).toFixed(1)}\" height=\"${plotH}\" fill=\"rgba(180,72,60,0.11)\"/>`;\n      }\n      // 当前选中道高亮底\n      if (isSel) {\n        h += `<rect x=\"${(cx - dx * 0.48).toFixed(1)}\" y=\"${T}\" width=\"${(dx * 0.96).toFixed(1)}\" height=\"${plotH}\" fill=\"rgba(18,97,90,0.10)\" stroke=\"#12615a\" stroke-width=\"1.2\" stroke-dasharray=\"3 2\"/>`;\n      }\n\n      // 道号与偏移距顶部标注\n      if (i % 2 === 0 || isSel || r.bt.isSpurious) {\n        const col = isSel ? '#12615a' : (r.bt.isSpurious ? '#b4483c' : '#5c6670');\n        h += `<text x=\"${cx.toFixed(1)}\" y=\"${T - 7}\" font-size=\"9\" font-family=\"ui-monospace,monospace\" font-weight=\"${isSel ? 700 : 500}\" fill=\"${col}\" text-anchor=\"middle\">#${r.bt.no}</text>`;\n      }\n\n      // 波形路径（采样步长 2 点以保证 SVG 极速流畅）\n      const scale = dx * 0.36;\n      let dLine = '';\n      let dArea = `M ${cx.toFixed(1)} ${T} `;\n      for (let s = 0; s < N_SAMPLES; s += 2) {\n        const y = yOf(s);\n        const amp = Math.max(-2.6, Math.min(2.6, r.wave[s]));\n        const x = cx + amp * scale;\n        dLine += (s === 0 ? 'M' : 'L') + x.toFixed(1) + ' ' + y.toFixed(1) + ' ';\n        const xPos = cx + Math.max(0, amp) * scale;\n        dArea += `L ${xPos.toFixed(1)} ${y.toFixed(1)} `;\n      }\n      dArea += `L ${cx.toFixed(1)} ${(T + plotH).toFixed(1)} Z`;\n\n      if (state.showVA) {\n        h += `<path d=\"${dArea}\" fill=\"${isSel ? 'rgba(18,97,90,0.42)' : 'rgba(36,45,54,0.28)'}\"/>`;\n      }\n      h += `<path d=\"${dLine}\" fill=\"none\" stroke=\"${isSel ? '#0f524c' : '#2a333c'}\" stroke-width=\"${isSel ? 1.25 : 0.85}\"/>`;\n\n      // 点击选道透明热区\n      h += `<rect x=\"${(cx - dx / 2).toFixed(1)}\" y=\"${T}\" width=\"${dx.toFixed(1)}\" height=\"${plotH}\" fill=\"transparent\" style=\"cursor:pointer\" data-tr-hit=\"${i}\"/>`;\n    });\n\n    // 真实初至走时曲线（绿色虚线）\n    const truePts = results.map((r, i) => `${xOf(i).toFixed(1)},${yOf(r.bt.idxTrue).toFixed(1)}`).join(' ');\n    h += `<polyline points=\"${truePts}\" fill=\"none\" stroke=\"#2f7d5b\" stroke-width=\"2\" stroke-dasharray=\"5 3\"/>`;\n\n    // 单道原始拾取点（橙色连线与圆点）\n    if (state.step >= 1) {\n      const rawPts = results.filter(r => r.singlePick > 0).map(r => `${xOf(r.bt.tr).toFixed(1)},${yOf(r.singlePick).toFixed(1)}`).join(' ');\n      if (rawPts) {\n        h += `<polyline points=\"${rawPts}\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"1.4\" stroke-dasharray=\"2 2\"/>`;\n      }\n      results.forEach((r, i) => {\n        if (r.singlePick > 0) {\n          h += `<circle cx=\"${xOf(i).toFixed(1)}\" cy=\"${yOf(r.singlePick).toFixed(1)}\" r=\"3.2\" fill=\"#c27a2c\" stroke=\"#fff\" stroke-width=\"0.8\"/>`;\n        }\n      });\n    }\n\n    // 空间一致性约束后最终初至曲线（深青色粗实线）\n    if (state.step >= 3 && state.spatial) {\n      const finPts = results.filter(r => r.finalPick > 0).map(r => `${xOf(r.bt.tr).toFixed(1)},${yOf(r.finalPick).toFixed(1)}`).join(' ');\n      h += `<polyline points=\"${finPts}\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.6\"/>`;\n      results.forEach((r, i) => {\n        if (r.finalPick > 0) {\n          h += `<circle cx=\"${xOf(i).toFixed(1)}\" cy=\"${yOf(r.finalPick).toFixed(1)}\" r=\"${r.corrected ? 4.5 : 3}\" fill=\"${r.corrected ? '#12615a' : '#0f766e'}\" stroke=\"#fff\" stroke-width=\"1.1\"/>`;\n        }\n      });\n    }\n\n    // 底部偏移距坐标轴标注\n    h += `<text x=\"${L}\" y=\"${H - 7}\" font-size=\"9.5\" font-family=\"ui-monospace,monospace\" fill=\"#5c6670\">偏移距 X = 50m (近道直达波 v₀≈750m/s)</text>`;\n    h += `<text x=\"${W - R}\" y=\"${H - 7}\" font-size=\"9.5\" font-family=\"ui-monospace,monospace\" fill=\"#5c6670\" text-anchor=\"end\">X = 1200m (远道折射波 v₁≈2100m/s) →</text>`;\n\n    svg.innerHTML = h;\n    svg.querySelectorAll('[data-tr-hit]').forEach(el => {\n      el.addEventListener('click', () => {\n        state.selTrace = +el.getAttribute('data-tr-hit');\n        updateAll();\n      });\n    });\n  }\n\n  // 渲染左下：选中道的单道显微镜（波形 + STA/LTA + AIC 局部曲线）\n  function renderMicroView(results) {\n    const svg = document.getElementById('svg-micro');\n    const r = results[state.selTrace];\n    if (!svg || !r) return;\n\n    document.getElementById('micro-title').textContent =\n      `第 #${r.bt.no} 道 (偏移距 ${r.bt.offset}m${r.bt.isSpurious ? ' · 含前驱脉冲干扰' : ''}) 波形 + STA/LTA + AIC 精修`;\n    document.getElementById('sel-badge').textContent =\n      `当前检视：第 #${r.bt.no} 道 (x=${r.bt.offset}m)`;\n\n    const W = 430, H = 250, L = 38, R = 14;\n    const xOf = idx => L + (idx / (N_SAMPLES - 1)) * (W - L - R);\n\n    // 上半框：单道滤波波形 (y: 14..120)\n    let h = `<rect x=\"${L}\" y=\"12\" width=\"${W - L - R}\" height=\"108\" fill=\"#fcfaf5\" stroke=\"#e2ddd2\"/>`;\n    h += `<line x1=\"${L}\" y1=\"66\" x2=\"${W - R}\" y2=\"66\" stroke=\"#dcd6c8\"/>`;\n    h += `<text x=\"${L - 5}\" y=\"24\" font-size=\"8.5\" font-family=\"ui-monospace,monospace\" fill=\"#6b747c\" text-anchor=\"end\">+A</text>`;\n    h += `<text x=\"${L - 5}\" y=\"69\" font-size=\"8.5\" font-family=\"ui-monospace,monospace\" fill=\"#6b747c\" text-anchor=\"end\">0</text>`;\n    h += `<text x=\"${L - 5}\" y=\"114\" font-size=\"8.5\" font-family=\"ui-monospace,monospace\" fill=\"#6b747c\" text-anchor=\"end\">-A</text>`;\n\n    let dWave = '';\n    for (let i = 0; i < N_SAMPLES; i++) {\n      const y = 66 - Math.max(-2.6, Math.min(2.6, r.wave[i])) * 18;\n      dWave += (i === 0 ? 'M' : 'L') + xOf(i).toFixed(1) + ' ' + y.toFixed(1) + ' ';\n    }\n    h += `<path d=\"${dWave}\" fill=\"none\" stroke=\"#3a6ea5\" stroke-width=\"1.2\"/>`;\n\n    // 下半框：STA/LTA 比值与阈值线 (y: 132..230)\n    h += `<rect x=\"${L}\" y=\"132\" width=\"${W - L - R}\" height=\"96\" fill=\"#fcfaf5\" stroke=\"#e2ddd2\"/>`;\n    const yRatio = val => 224 - (Math.min(10, Math.max(0, val)) / 10) * 86;\n    const yThr = yRatio(state.thr);\n    h += `<line x1=\"${L}\" y1=\"${yThr.toFixed(1)}\" x2=\"${W - R}\" y2=\"${yThr.toFixed(1)}\" stroke=\"#b4483c\" stroke-width=\"1.1\" stroke-dasharray=\"4 3\"/>`;\n    h += `<text x=\"${W - R - 4}\" y=\"${(yThr - 4).toFixed(1)}\" font-size=\"8.5\" font-family=\"ui-monospace,monospace\" fill=\"#b4483c\" text-anchor=\"end\">阈值 ${state.thr.toFixed(1)}</text>`;\n\n    let dRat = '';\n    for (let i = 0; i < N_SAMPLES; i++) {\n      dRat += (i === 0 ? 'M' : 'L') + xOf(i).toFixed(1) + ' ' + yRatio(r.ratio[i]).toFixed(1) + ' ';\n    }\n    h += `<path d=\"${dRat}\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"1.35\"/>`;\n\n    // 真实初至、单道拾取、最终拾取三条竖线贯穿上下图\n    const xTrue = xOf(r.bt.idxTrue);\n    h += `<line x1=\"${xTrue.toFixed(1)}\" y1=\"12\" x2=\"${xTrue.toFixed(1)}\" y2=\"228\" stroke=\"#2f7d5b\" stroke-width=\"1.5\" stroke-dasharray=\"4 3\"/>`;\n    h += `<text x=\"${(xTrue + 4).toFixed(1)}\" y=\"24\" font-size=\"9\" font-weight=\"700\" fill=\"#2f7d5b\">真值 ${r.bt.idxTrue * DT}ms</text>`;\n\n    if (r.singlePick > 0) {\n      const xRaw = xOf(r.singlePick);\n      h += `<line x1=\"${xRaw.toFixed(1)}\" y1=\"12\" x2=\"${xRaw.toFixed(1)}\" y2=\"228\" stroke=\"#c27a2c\" stroke-width=\"1.4\" stroke-dasharray=\"2 2\"/>`;\n      h += `<text x=\"${(xRaw - 4).toFixed(1)}\" y=\"114\" font-size=\"8.8\" fill=\"#c27a2c\" text-anchor=\"end\">单道 ${r.singlePick * DT}ms</text>`;\n    }\n\n    const finIdx = state.spatial ? r.finalPick : r.singlePick;\n    if (finIdx > 0) {\n      const xFin = xOf(finIdx);\n      h += `<line x1=\"${xFin.toFixed(1)}\" y1=\"12\" x2=\"${xFin.toFixed(1)}\" y2=\"228\" stroke=\"#12615a\" stroke-width=\"2.1\"/>`;\n      h += `<text x=\"${(xFin + 4).toFixed(1)}\" y=\"146\" font-size=\"9\" font-weight=\"700\" fill=\"#12615a\">采用 ${finIdx * DT}ms</text>`;\n    }\n\n    h += `<text x=\"${W - R}\" y=\"244\" font-size=\"9\" font-family=\"ui-monospace,monospace\" fill=\"#6b747c\" text-anchor=\"end\">采样时间 t (0 — 720 ms) →</text>`;\n    svg.innerHTML = h;\n  }\n\n  // 渲染右下：折射走时拟合表层速度与逐道绝对误差柱状图\n  function renderRefracAndError(results) {\n    const svg = document.getElementById('svg-refrac');\n    if (!svg) return;\n    const W = 430, H = 250, L = 42, R = 14;\n    const plotW = W - L - R;\n    const xOf = tr => L + (tr + 0.5) * (plotW / N_TRACES);\n\n    // 上半部分：偏移距-走时折线拟合 (t: 0..900ms -> y: 112..14)\n    const yT = ms => 112 - (ms / 900) * 96;\n    let h = `<rect x=\"${L}\" y=\"12\" width=\"${plotW}\" height=\"102\" fill=\"#fcfaf5\" stroke=\"#e2ddd2\"/>`;\n    h += `<text x=\"${L + 6}\" y=\"25\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">双层折射走时反演：v₀≈750m/s, v₁≈2100m/s, 拐点 Xc≈290m</text>`;\n\n    // 直达波与折射波理论折线\n    const xCross = L + (290 / 1200) * plotW;\n    h += `<line x1=\"${L}\" y1=\"${yT(0).toFixed(1)}\" x2=\"${xCross.toFixed(1)}\" y2=\"${yT(387).toFixed(1)}\" stroke=\"#2f7d5b\" stroke-width=\"1.5\" stroke-dasharray=\"4 2\"/>`;\n    h += `<line x1=\"${xCross.toFixed(1)}\" y1=\"${yT(398).toFixed(1)}\" x2=\"${W - R}\" y2=\"${yT(831).toFixed(1)}\" stroke=\"#12615a\" stroke-width=\"1.8\"/>`;\n\n    results.forEach((r, i) => {\n      const pIdx = state.spatial ? r.finalPick : r.singlePick;\n      if (pIdx > 0) {\n        h += `<circle cx=\"${xOf(i).toFixed(1)}\" cy=\"${yT(pIdx * DT).toFixed(1)}\" r=\"2.6\" fill=\"${r.corrected ? '#12615a' : '#c27a2c'}\"/>`;\n      }\n    });\n\n    // 下半部分：约束前后逐道绝对误差 |Δt| (0..80 ms -> y: 230..132)\n    const yE = errMs => 230 - (Math.min(80, errMs) / 80) * 94;\n    h += `<rect x=\"${L}\" y=\"132\" width=\"${plotW}\" height=\"98\" fill=\"#fcfaf5\" stroke=\"#e2ddd2\"/>`;\n    const yTol = yE(4); // 4ms 验收容差线\n    h += `<line x1=\"${L}\" y1=\"${yTol.toFixed(1)}\" x2=\"${W - R}\" y2=\"${yTol.toFixed(1)}\" stroke=\"#2f7d5b\" stroke-width=\"1.1\" stroke-dasharray=\"4 3\"/>`;\n    h += `<text x=\"${W - R - 4}\" y=\"${(yTol - 4).toFixed(1)}\" font-size=\"8.5\" font-family=\"ui-monospace,monospace\" fill=\"#2f7d5b\" text-anchor=\"end\">验收阈值 ≤4ms</text>`;\n\n    results.forEach((r, i) => {\n      const cx = xOf(i);\n      const rawErr = r.singlePick < 0 ? 80 : Math.abs(r.singlePick - r.bt.idxTrue) * DT;\n      const finPick = state.spatial ? r.finalPick : r.singlePick;\n      const finErr = finPick < 0 ? 80 : Math.abs(finPick - r.bt.idxTrue) * DT;\n\n      // 原始误差橙色细条\n      const yR0 = yE(rawErr);\n      h += `<rect x=\"${(cx - 4.5).toFixed(1)}\" y=\"${yR0.toFixed(1)}\" width=\"4\" height=\"${(230 - yR0).toFixed(1)}\" fill=\"#c27a2c\" opacity=\"0.75\"/>`;\n      // 约束后误差青色条\n      const yF0 = yE(finErr);\n      h += `<rect x=\"${(cx + 0.5).toFixed(1)}\" y=\"${yF0.toFixed(1)}\" width=\"4\" height=\"${(230 - yF0).toFixed(1)}\" fill=\"#12615a\"/>`;\n    });\n\n    h += `<text x=\"${L}\" y=\"244\" font-size=\"9\" font-family=\"ui-monospace,monospace\" fill=\"#6b747c\">道号 #1 — #24 逐道绝对拾取误差 |Δt| (ms)</text>`;\n    svg.innerHTML = h;\n  }\n\n  // 更新 KPI 与解读文字\n  function renderStats(results) {\n    let rawHits = 0, finHits = 0, rawErrSum = 0, finErrSum = 0, nFixed = 0, nQC = 0;\n    results.forEach(r => {\n      const rErr = r.singlePick < 0 ? 60 : Math.abs(r.singlePick - r.bt.idxTrue) * DT;\n      const fPick = state.spatial ? r.finalPick : r.singlePick;\n      const fErr = fPick < 0 ? 60 : Math.abs(fPick - r.bt.idxTrue) * DT;\n      if (rErr <= 4) rawHits++;\n      if (fErr <= 4) finHits++;\n      rawErrSum += rErr;\n      finErrSum += fErr;\n      if (r.corrected) nFixed++;\n      if (r.lowConf) nQC++;\n    });\n\n    const hitPct = ((finHits / N_TRACES) * 100).toFixed(1);\n    const rawHitPct = ((rawHits / N_TRACES) * 100).toFixed(1);\n    const mae = (finErrSum / N_TRACES).toFixed(1);\n    const rawMae = (rawErrSum / N_TRACES).toFixed(1);\n    const qcPct = ((nQC / N_TRACES) * 100).toFixed(1);\n\n    document.getElementById('val-hit').textContent = hitPct;\n    document.getElementById('sub-hit').textContent = `单道原始命中率 ${rawHitPct}%`;\n    document.getElementById('kpi-hit').className = +hitPct >= 90 ? 'kpi ok' : 'kpi warn';\n\n    document.getElementById('val-mae').textContent = mae;\n    document.getElementById('sub-mae').textContent = `约束前原始误差 ${rawMae} ms`;\n\n    document.getElementById('val-fix').textContent = state.spatial ? nFixed : 0;\n    document.getElementById('sub-fix').textContent = state.spatial ? '已拦截前驱脉冲假拾取并邻道回退' : '空间一致性约束已关闭（离群道暴露）';\n\n    document.getElementById('val-qc').textContent = qcPct;\n    document.getElementById('sub-qc').textContent = `仅需人工复核 ${nQC} 道 (节省 ${(100 - qcPct).toFixed(1)}% 工时)`;\n    document.getElementById('pill-status-txt').textContent =\n      `命中率 ${hitPct}% · ${state.spatial ? '空间约束已生效' : '无空间约束'}`;\n\n    const cur = results[state.selTrace];\n    const stepNotes = [\n      `<b>STEP 01 道集解编与带通滤波</b>：对 24 道单炮记录去直流并施加 10–80 Hz 零相位带通滤波，压制部分低频面波（蓝色虚线锥）。`,\n      `<b>STEP 02 逐道能量比/概率扫描</b>：使用短窗 STA=${state.sta} 点与长窗 LTA=${LTA_WIN} 点扫描波形，但在 <b>#7、#14、#21</b> 等含突发前驱脉冲道上，单道阈值（${state.thr.toFixed(1)}）被提前误触发，原始命中率仅 <b>${rawHitPct}%</b>。`,\n      `<b>STEP 03 AIC 局部极小值精修</b>：在粗触发点邻域内计算赤池信息准则（AIC），将因短窗积分滞后的拾取点拉回波至起跳极小值，降低系统性正偏。`,\n      `<b>STEP 04 炮集空间走时一致性约束</b>：利用相邻道初至沿偏移距呈分段线性（直达波 $v_0\\\\approx 750\\\\text{ m/s}$、折射波 $v_1\\\\approx 2100\\\\text{ m/s}$）的物理规律，自动识别并回退偏离中位数 >3.5 采样点的 <b>${nFixed} 条异常道</b>，全炮 MAE 从 <b>${rawMae} ms</b> 降至 <b>${mae} ms</b>。`,\n      `<b>STEP 05 低置信度道排序与人工复核</b>：系统仅将回退修正道与低信噪比道（共 <b>${nQC} 道，占 ${qcPct}%</b>）标红推送人工质控。当前选中 <b>第 #${cur.bt.no} 道</b>，真实初至 <b>${cur.bt.idxTrue * DT} ms</b>，最终拾取 <b>${(state.spatial ? cur.finalPick : cur.singlePick) * DT} ms</b>。`\n    ];\n    document.getElementById('insight-text').innerHTML = stepNotes[state.step] || stepNotes[4];\n  }\n\n  function updateAll() {\n    const results = computeGather();\n    renderTracePills(results);\n    renderShotGather(results);\n    renderMicroView(results);\n    renderRefracAndError(results);\n    renderStats(results);\n  }\n\n  function bindEvents() {\n    document.querySelectorAll('#stepper button').forEach(btn => {\n      btn.addEventListener('click', () => {\n        state.step = +btn.dataset.step;\n        document.querySelectorAll('#stepper button').forEach((b, i) => {\n          b.classList.toggle('on', i === state.step);\n          b.classList.toggle('done', i < state.step);\n        });\n        updateAll();\n      });\n    });\n\n    document.querySelectorAll('#method-seg button').forEach(btn => {\n      btn.addEventListener('click', () => {\n        state.method = btn.dataset.method;\n        document.querySelectorAll('#method-seg button').forEach(b => b.classList.toggle('on', b === btn));\n        updateAll();\n      });\n    });\n\n    document.getElementById('sl-noise').addEventListener('input', e => {\n      state.noise = +e.target.value;\n      document.getElementById('out-noise').textContent = state.noise.toFixed(2);\n      updateAll();\n    });\n    document.getElementById('sl-thr').addEventListener('input', e => {\n      state.thr = +e.target.value;\n      document.getElementById('out-thr').textContent = state.thr.toFixed(1);\n      updateAll();\n    });\n    document.getElementById('sl-sta').addEventListener('input', e => {\n      state.sta = +e.target.value;\n      document.getElementById('out-sta').textContent = `${state.sta} 点 (${state.sta * DT}ms)`;\n      updateAll();\n    });\n\n    document.getElementById('chk-spatial').addEventListener('change', e => {\n      state.spatial = e.target.checked;\n      updateAll();\n    });\n    document.getElementById('chk-va').addEventListener('change', e => {\n      state.showVA = e.target.checked;\n      updateAll();\n    });\n    document.getElementById('chk-qc').addEventListener('change', e => {\n      state.showQC = e.target.checked;\n      updateAll();\n    });\n\n    document.getElementById('btn-demo').addEventListener('click', () => {\n      state.noise = 2.15; state.thr = 2.6; state.spatial = false; state.selTrace = 13;\n      document.getElementById('sl-noise').value = 2.15; document.getElementById('out-noise').textContent = '2.15';\n      document.getElementById('sl-thr').value = 2.6; document.getElementById('out-thr').textContent = '2.6';\n      document.getElementById('chk-spatial').checked = false;\n      updateAll();\n    });\n\n    document.getElementById('btn-reset').addEventListener('click', () => {\n      state.step = 4; state.method = 'aic'; state.noise = 1.10; state.thr = 3.2; state.sta = 8;\n      state.spatial = true; state.showVA = true; state.showQC = true; state.selTrace = 13;\n      document.getElementById('sl-noise').value = 1.10; document.getElementById('out-noise').textContent = '1.10';\n      document.getElementById('sl-thr').value = 3.2; document.getElementById('out-thr').textContent = '3.2';\n      document.getElementById('sl-sta').value = 8; document.getElementById('out-sta').textContent = '8 点 (16ms)';\n      document.getElementById('chk-spatial').checked = true;\n      document.getElementById('chk-va').checked = true;\n      document.getElementById('chk-qc').checked = true;\n      document.querySelectorAll('#method-seg button').forEach(b => b.classList.toggle('on', b.dataset.method === 'aic'));\n      updateAll();\n    });\n  }\n\n  bindEvents();\n  updateAll();\n})();\n","enc":"text","size":27292}]};